Semaphore mutex; //访问邮箱的互斥量
Semaphore empty=N,full=0;
Yonghu(){
    //用户
    while(1){
        P(empty); //检查邮箱空否
        P(mutex); //互斥访问邮箱
        发送邮件;
        V(mutex);
        V(full);
    }
}
ZHuRen(){
    //邮箱主人
    while(1){
        P(full); //检查邮箱是否有邮件
        P(mutex); //互斥访问邮箱
        读邮件;
        V(mutex);
        V(empty); //自动删除读过的邮件
    }
}

